    let camera = Camera::new(2.0);
    let mut rays = Vec::new();
    for &(u, v) in &PROBES {
        rays.push(camera.ray(u, v));
    }
    for (r, &(u, v)) in rays.iter().zip(&PROBES) {
        println!("pixel ({u}, {v}) -> direction {:?}", r.dir);
    }
    println!("two units along the centre ray: {:?}", rays[3].at(2.0));
    rays
}

