            Some((scattered, albedo)) => albedo * ray_colour(&scattered, world, rng, depth - 1),
            None => vec3(0.0, 0.0, 0.0),
        };
    }
    let t = 0.5 * (r.dir.unit().y + 1.0);
    vec3(1.0, 1.0, 1.0) * (1.0 - t) + vec3(0.5, 0.7, 1.0) * t
